-- Colombia story arc: 2 stories spanning the past ~7 months, tracking
-- DIAN's continued procedural activity well after the mandate went
-- universal in 2020 -- the September 2025 regulatory unification
-- (Resolution 000227/2025) and the April 2026 e-invoicing
-- regularization mechanism (Resolution 000011/2026), matching the
-- multi-story arc pattern used for countries with ongoing policy
-- activity rather than a single launch event (see Argentina's
-- 319, the Netherlands' 221-222).

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-09-23-colombia-unified-resolution', '2025-09-23', '2025-09', 'DIAN folded its e-invoicing rules -- along with more than 60 other scattered tax resolutions -- into a single unified resolution, 000227/2025, taking effect today.', '<h3>🇨🇴 DIAN consolidates decades of tax rules, e-invoicing included, into one resolution</h3>
<p>Colombia''s e-invoicing rules have been built up piece by piece since 2018: Resolution 000010/2018 for large taxpayers, Resolution 000042/2020 for the universal rollout, Resolution 000165/2023 for equivalent documents, and more besides. As of today, Resolution 000227/2025 folds all of it -- plus more than 60 other tax, customs, and foreign-exchange resolutions dating back to the late 1990s -- into a single unified regulatory text.</p>
<p>DIAN is explicit that this is organizational, not substantive: "no es una reforma que cambie las reglas de forma radical; es un complemento de organización y unificación." E-invoicing and equivalent-document rules now live in Title IV of Part I, incorporating Resolution 000165/2023 as Title 5 with its technical annex re-coded T5.1. Nothing a compliant business is already doing changes.</p>
<p>The practical upside is navigability: instead of tracking which of a dozen resolutions currently governs a given requirement, businesses and their advisors now have one normative reference to consult. For a mandate this mature, that kind of housekeeping is itself a sign of how much regulatory surface area has accumulated since 2018.</p>', 'https://actualicese.com/lo-que-debes-saber-sobre-la-unificacion-de-reportes-segun-la-resolucion-dian-000227-de-2025/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2025-09-23-colombia-unified-resolution', id FROM countries WHERE name_en = 'Colombia';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-09-23-colombia-unified-resolution', 'en', 'DIAN consolidates decades of tax rules, e-invoicing included, into one resolution', 'DIAN folded its e-invoicing rules -- along with more than 60 other scattered tax resolutions -- into a single unified resolution, 000227/2025, taking effect today.', '<h3>🇨🇴 DIAN consolidates decades of tax rules, e-invoicing included, into one resolution</h3>
<p>Colombia''s e-invoicing rules have been built up piece by piece since 2018: Resolution 000010/2018 for large taxpayers, Resolution 000042/2020 for the universal rollout, Resolution 000165/2023 for equivalent documents, and more besides. As of today, Resolution 000227/2025 folds all of it -- plus more than 60 other tax, customs, and foreign-exchange resolutions dating back to the late 1990s -- into a single unified regulatory text.</p>
<p>DIAN is explicit that this is organizational, not substantive: "no es una reforma que cambie las reglas de forma radical; es un complemento de organización y unificación." E-invoicing and equivalent-document rules now live in Title IV of Part I, incorporating Resolution 000165/2023 as Title 5 with its technical annex re-coded T5.1. Nothing a compliant business is already doing changes.</p>
<p>The practical upside is navigability: instead of tracking which of a dozen resolutions currently governs a given requirement, businesses and their advisors now have one normative reference to consult. For a mandate this mature, that kind of housekeeping is itself a sign of how much regulatory surface area has accumulated since 2018.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-09-23-colombia-unified-resolution', 'es', 'La DIAN consolida décadas de normas tributarias, incluida la facturación electrónica, en una sola resolución', 'La DIAN unificó sus normas de facturación electrónica -- junto con más de 60 otras resoluciones tributarias dispersas -- en una sola resolución unificada, la 000227 de 2025, vigente desde hoy.', '<h3>🇨🇴 La DIAN consolida décadas de normas tributarias, incluida la facturación electrónica, en una sola resolución</h3>
<p>Las normas de facturación electrónica de Colombia se han construido pieza por pieza desde 2018: la Resolución 000010 de 2018 para grandes contribuyentes, la Resolución 000042 de 2020 para la implementación universal, la Resolución 000165 de 2023 para documentos equivalentes, y más. Desde hoy, la Resolución 000227 de 2025 reúne todo eso -- además de más de 60 otras resoluciones tributarias, aduaneras y cambiarias que se remontan a finales de los años noventa -- en un único texto normativo unificado.</p>
<p>La DIAN es explícita en que esto es organizativo, no sustantivo: "no es una reforma que cambie las reglas de forma radical; es un complemento de organización y unificación." Las normas de facturación electrónica y documentos equivalentes ahora viven en el Título IV de la Parte I, incorporando la Resolución 000165 de 2023 como Título 5 con su anexo técnico recodificado como T5.1. Nada de lo que ya hace una empresa cumplida cambia.</p>
<p>La ventaja práctica es la navegabilidad: en lugar de rastrear cuál de una docena de resoluciones rige actualmente un requisito dado, las empresas y sus asesores ahora tienen una sola referencia normativa que consultar. Para un mandato tan maduro, ese tipo de orden es en sí mismo una señal de cuánta superficie regulatoria se ha acumulado desde 2018.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-09-23-colombia-unified-resolution', 'de', 'DIAN konsolidiert jahrzehntealte Steuervorschriften, einschließlich der elektronischen Rechnungsstellung, in einer Resolution', 'Die DIAN hat ihre Vorschriften zur elektronischen Rechnungsstellung -- zusammen mit mehr als 60 weiteren verstreuten Steuerresolutionen -- in einer einzigen, ab heute geltenden Resolution, 000227/2025, zusammengefasst.', '<h3>🇨🇴 DIAN konsolidiert jahrzehntealte Steuervorschriften, einschließlich der elektronischen Rechnungsstellung, in einer Resolution</h3>
<p>Kolumbiens Vorschriften zur elektronischen Rechnungsstellung wurden seit 2018 Stück für Stück aufgebaut: Resolution 000010/2018 für Großsteuerpflichtige, Resolution 000042/2020 für den universellen Rollout, Resolution 000165/2023 für gleichwertige Dokumente, und mehr. Ab heute fasst die Resolution 000227/2025 all das -- zusammen mit mehr als 60 weiteren Steuer-, Zoll- und Devisenresolutionen, die bis in die späten 1990er Jahre zurückreichen -- in einem einzigen einheitlichen Regelwerk zusammen.</p>
<p>Die DIAN stellt ausdrücklich klar, dass dies organisatorisch und nicht inhaltlich gemeint ist: "no es una reforma que cambie las reglas de forma radical; es un complemento de organización y unificación." Die Regeln zur elektronischen Rechnungsstellung und zu gleichwertigen Dokumenten befinden sich nun in Titel IV von Teil I, wobei die Resolution 000165/2023 als Titel 5 mit neu kodiertem technischem Anhang T5.1 eingegliedert wurde. Für ein bereits konformes Unternehmen ändert sich nichts an der laufenden Praxis.</p>
<p>Der praktische Vorteil liegt in der besseren Navigierbarkeit: Statt nachzuverfolgen, welche von einem Dutzend Resolutionen eine bestimmte Anforderung aktuell regelt, haben Unternehmen und ihre Berater nun eine einzige normative Referenz. Für ein derart ausgereiftes Mandat ist eine solche Aufräumaktion selbst ein Zeichen dafür, wie viel regulatorische Fläche sich seit 2018 angesammelt hat.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-09-23-colombia-unified-resolution', 'fr', 'La DIAN regroupe des décennies de règles fiscales, facturation électronique incluse, en une seule résolution', 'La DIAN a regroupé ses règles de facturation électronique -- ainsi que plus de 60 autres résolutions fiscales dispersées -- en une résolution unifiée unique, la 000227/2025, entrée en vigueur aujourd''hui.', '<h3>🇨🇴 La DIAN regroupe des décennies de règles fiscales, facturation électronique incluse, en une seule résolution</h3>
<p>Les règles de facturation électronique de la Colombie ont été bâties morceau par morceau depuis 2018 : la résolution 000010/2018 pour les grands contribuables, la résolution 000042/2020 pour le déploiement universel, la résolution 000165/2023 pour les documents équivalents, et bien d''autres encore. Depuis aujourd''hui, la résolution 000227/2025 regroupe l''ensemble -- ainsi que plus de 60 autres résolutions fiscales, douanières et de change remontant à la fin des années 1990 -- en un texte réglementaire unifié unique.</p>
<p>La DIAN précise explicitement qu''il s''agit d''une démarche organisationnelle et non substantielle : "no es una reforma que cambie las reglas de forma radical; es un complemento de organización y unificación." Les règles de facturation électronique et de documents équivalents figurent désormais au Titre IV de la Partie I, la résolution 000165/2023 y étant intégrée sous le Titre 5 avec son annexe technique recodée T5.1. Rien de ce qu''une entreprise déjà conforme fait actuellement ne change.</p>
<p>L''avantage pratique réside dans la facilité de navigation : plutôt que de suivre laquelle, parmi une dizaine de résolutions, régit actuellement une exigence donnée, les entreprises et leurs conseillers disposent désormais d''une référence normative unique à consulter. Pour un mandat aussi mature, ce type de rangement est en soi le signe de l''ampleur de la surface réglementaire accumulée depuis 2018.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-04-23-colombia-regularization-mechanism', '2026-04-23', '2026-04', 'DIAN''s Resolution 000011/2026 opens a voluntary "20-REG" mechanism letting businesses regularize past e-invoicing gaps by transmitting the missed operations retroactively.', '<h3>🇨🇴 DIAN opens a one-time path to fix skipped invoices</h3>
<p>Resolution 000011/2026, issued 23 April 2026, gives Colombian businesses a formal way to come clean about e-invoicing they should have issued but didn''t. Under the new mechanism, a business generates and transmits electronic invoices for previously unissued or improperly issued operations, tagging them as invoice type 3 with the special code "20-REG" in the CustomizationID field.</p>
<p>The code lets DIAN treat these catch-up invoices differently from ordinary ones -- relaxing typical sequence and timing validations so a business can invoice an operation dated months earlier without the system rejecting it as out of order. The mechanism traces back to Article 5 of Legislative Decree 0240/2026, part of a broader emergency tax decree issued in March 2026, though its scope here is narrowly about e-invoicing.</p>
<p>DIAN frames this as reducing fiscal risk and improving traceability for genuine past gaps, not as a general amnesty -- the resolution doesn''t limit DIAN''s ordinary enforcement powers for anything going forward. As Sovos Saphety''s Alejandro Silva put it, this reflects "una evolución del modelo de control tributario hacia mecanismos más estructurados y trazables" -- a tax authority increasingly building tools around the data it already collects in real time.</p>', 'https://lanotaeconomica.com.co/movidas-empresarial/dian-publica-nuevo-proyecto-de-resolucion-para-regularizar-incumplimientos-en-facturacion-electronica/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-04-23-colombia-regularization-mechanism', id FROM countries WHERE name_en = 'Colombia';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-23-colombia-regularization-mechanism', 'en', 'DIAN opens a one-time path to fix skipped invoices', 'DIAN''s Resolution 000011/2026 opens a voluntary "20-REG" mechanism letting businesses regularize past e-invoicing gaps by transmitting the missed operations retroactively.', '<h3>🇨🇴 DIAN opens a one-time path to fix skipped invoices</h3>
<p>Resolution 000011/2026, issued 23 April 2026, gives Colombian businesses a formal way to come clean about e-invoicing they should have issued but didn''t. Under the new mechanism, a business generates and transmits electronic invoices for previously unissued or improperly issued operations, tagging them as invoice type 3 with the special code "20-REG" in the CustomizationID field.</p>
<p>The code lets DIAN treat these catch-up invoices differently from ordinary ones -- relaxing typical sequence and timing validations so a business can invoice an operation dated months earlier without the system rejecting it as out of order. The mechanism traces back to Article 5 of Legislative Decree 0240/2026, part of a broader emergency tax decree issued in March 2026, though its scope here is narrowly about e-invoicing.</p>
<p>DIAN frames this as reducing fiscal risk and improving traceability for genuine past gaps, not as a general amnesty -- the resolution doesn''t limit DIAN''s ordinary enforcement powers for anything going forward. As Sovos Saphety''s Alejandro Silva put it, this reflects "una evolución del modelo de control tributario hacia mecanismos más estructurados y trazables" -- a tax authority increasingly building tools around the data it already collects in real time.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-23-colombia-regularization-mechanism', 'es', 'La DIAN abre una vía única para corregir facturas omitidas', 'La Resolución 000011 de 2026 de la DIAN abre un mecanismo voluntario "20-REG" que permite a las empresas regularizar brechas pasadas de facturación electrónica transmitiendo de forma retroactiva las operaciones omitidas.', '<h3>🇨🇴 La DIAN abre una vía única para corregir facturas omitidas</h3>
<p>La Resolución 000011 de 2026, emitida el 23 de abril de 2026, da a las empresas colombianas una vía formal para regularizar la facturación electrónica que debieron emitir y no emitieron. Bajo el nuevo mecanismo, una empresa genera y transmite facturas electrónicas para operaciones previamente no facturadas o facturadas de forma incorrecta, marcándolas como factura tipo 3 con el código especial "20-REG" en el campo CustomizationID.</p>
<p>El código permite a la DIAN tratar estas facturas de puesta al día de forma diferente a las ordinarias -- relajando las validaciones habituales de secuencia y tiempo para que una empresa pueda facturar una operación con fecha de meses atrás sin que el sistema la rechace por estar fuera de orden. El mecanismo se remonta al artículo 5 del Decreto Legislativo 0240 de 2026, parte de un decreto tributario de emergencia más amplio emitido en marzo de 2026, aunque su alcance aquí se limita estrictamente a la facturación electrónica.</p>
<p>La DIAN presenta esto como una reducción del riesgo fiscal y una mejora de la trazabilidad para brechas pasadas genuinas, no como una amnistía general -- la resolución no limita las facultades ordinarias de fiscalización de la DIAN hacia adelante. Como lo expresó Alejandro Silva, de Sovos Saphety, esto refleja "una evolución del modelo de control tributario hacia mecanismos más estructurados y trazables" -- una autoridad fiscal que construye cada vez más herramientas alrededor de los datos que ya recopila en tiempo real.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-23-colombia-regularization-mechanism', 'de', 'DIAN eröffnet einen einmaligen Weg zur Korrektur versäumter Rechnungen', 'Die Resolution 000011/2026 der DIAN eröffnet einen freiwilligen "20-REG"-Mechanismus, der Unternehmen erlaubt, vergangene Lücken bei der elektronischen Rechnungsstellung durch nachträgliche Übermittlung der versäumten Vorgänge zu regularisieren.', '<h3>🇨🇴 DIAN eröffnet einen einmaligen Weg zur Korrektur versäumter Rechnungen</h3>
<p>Die am 23. April 2026 erlassene Resolution 000011/2026 gibt kolumbianischen Unternehmen einen formellen Weg, versäumte elektronische Rechnungsstellung nachzuholen. Im Rahmen des neuen Mechanismus erstellt und übermittelt ein Unternehmen elektronische Rechnungen für zuvor nicht oder fehlerhaft fakturierte Vorgänge und kennzeichnet sie als Rechnungstyp 3 mit dem speziellen Code "20-REG" im Feld CustomizationID.</p>
<p>Der Code erlaubt es der DIAN, diese Nachhol-Rechnungen anders zu behandeln als gewöhnliche -- übliche Reihenfolge- und Zeitvalidierungen werden gelockert, sodass ein Unternehmen einen Monate zurückliegenden Vorgang fakturieren kann, ohne dass das System ihn als nicht ordnungsgemäß abweist. Der Mechanismus geht auf Artikel 5 des Legislativdekrets 0240/2026 zurück, Teil eines umfassenderen im März 2026 erlassenen Steuernotstandsdekrets, wobei sein Anwendungsbereich hier eng auf die elektronische Rechnungsstellung begrenzt ist.</p>
<p>Die DIAN stellt dies als Verringerung des steuerlichen Risikos und Verbesserung der Nachverfolgbarkeit für echte vergangene Lücken dar, nicht als allgemeine Amnestie -- die Resolution schränkt die üblichen Durchsetzungsbefugnisse der DIAN für die Zukunft nicht ein. Wie Alejandro Silva von Sovos Saphety es ausdrückte, spiegelt dies "una evolución del modelo de control tributario hacia mecanismos más estructurados y trazables" wider -- eine Steuerbehörde, die zunehmend Werkzeuge rund um die Daten baut, die sie bereits in Echtzeit erfasst.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-23-colombia-regularization-mechanism', 'fr', 'La DIAN ouvre une voie unique pour corriger les factures omises', 'La résolution 000011/2026 de la DIAN ouvre un mécanisme volontaire "20-REG" permettant aux entreprises de régulariser leurs lacunes passées de facturation électronique en transmettant rétroactivement les opérations omises.', '<h3>🇨🇴 La DIAN ouvre une voie unique pour corriger les factures omises</h3>
<p>La résolution 000011/2026, émise le 23 avril 2026, offre aux entreprises colombiennes un moyen formel de régulariser la facturation électronique qu''elles auraient dû émettre mais n''ont pas émise. Dans le cadre de ce nouveau mécanisme, une entreprise génère et transmet des factures électroniques pour des opérations antérieurement non facturées ou mal facturées, en les identifiant comme facture de type 3 avec le code spécial "20-REG" dans le champ CustomizationID.</p>
<p>Ce code permet à la DIAN de traiter ces factures de rattrapage différemment des factures ordinaires -- en assouplissant les validations habituelles de séquence et de délai, afin qu''une entreprise puisse facturer une opération datant de plusieurs mois sans que le système ne la rejette pour non-conformité d''ordre. Le mécanisme trouve son origine dans l''article 5 du décret législatif 0240/2026, qui s''inscrit dans un décret fiscal d''urgence plus large publié en mars 2026, bien que sa portée ici se limite strictement à la facturation électronique.</p>
<p>La DIAN présente cela comme une réduction du risque fiscal et une amélioration de la traçabilité pour de véritables lacunes passées, non comme une amnistie générale -- la résolution ne limite pas les pouvoirs ordinaires de contrôle de la DIAN pour l''avenir. Comme l''a formulé Alejandro Silva, de Sovos Saphety, cela reflète "una evolución del modelo de control tributario hacia mecanismos más estructurados y trazables" -- une administration fiscale qui construit de plus en plus d''outils autour des données qu''elle collecte déjà en temps réel.</p>');
